const place=$('Extract Place').first().json.place;
const wx=$('Open-Meteo Forecast').first().json;
const aq=$json;
const current=wx.current||{},hourly=wx.hourly||{};
const times=hourly.time||[];
let idx=times.findIndex(t=>t>=(current.time||'').slice(0,13)+':00'); if(idx<0) idx=0;
const sl=(a,n=12)=>(a||[]).slice(idx,idx+n);
const rain=Math.max(...sl(hourly.precipitation_probability),0);
const gust=Math.max(...sl(hourly.wind_gusts_10m),current.wind_gusts_10m||0);
const uv=Math.max(...sl(hourly.uv_index),0);
const visVals=sl(hourly.visibility).filter(Number.isFinite); const minVis=visVals.length?Math.min(...visVals):100000;
const codes=sl(hourly.weather_code);
let score=0,reasons=[];
if(rain>=85){score+=30;reasons.push('Very high rain probability')} else if(rain>=60){score+=18;reasons.push('Rain likely')} else if(rain>=35){score+=8;reasons.push('Possible rain')}
if(gust>=55){score+=25;reasons.push('Strong wind gusts')} else if(gust>=38){score+=13;reasons.push('Gusty wind')}
if(codes.some(c=>[95,96,99].includes(c))){score+=30;reasons.push('Thunderstorm signal')}
const feels=current.apparent_temperature??current.temperature_2m??0;
if(feels>=42){score+=24;reasons.push('Extreme heat stress')} else if(feels>=37){score+=12;reasons.push('High heat')}
if(uv>=8){score+=10;reasons.push('Very high UV')}
if(minVis<3000){score+=12;reasons.push('Poor visibility')} else if(minVis<7000){score+=5;reasons.push('Reduced visibility')}
score=Math.min(100,score);
const level=score>=81?'EXTREME':score>=61?'HIGH':score>=41?'ELEVATED':score>=21?'MODERATE':'LOW';
const clamp=x=>Math.max(0,Math.min(100,Math.round(x)));
const activityBase=(rainW,heatW,windStart,windW,uvStart=7,uvW=3,storm=50,visPenalty=10)=>{let v=100-rain*rainW-Math.max(0,feels-31)*heatW-Math.max(0,gust-windStart)*windW-Math.max(0,uv-uvStart)*uvW-(codes.some(c=>[95,96,99].includes(c))?storm:0)-(minVis<3000?visPenalty:minVis<7000?visPenalty*.45:0);return clamp(v)};
const humidity=Number(current.relative_humidity_2m??60);
const activities={
  Running:activityBase(.24,3.4,28,1.1,6,3.5,55,12),
  Walking:activityBase(.17,2.6,38,.45,7,2.5,48,8),
  Cycling:activityBase(.30,3.0,24,1.7,7,2.8,60,22),
  Cricket:activityBase(.43,2.7,34,.9,7,2.8,65,12),
  Football:activityBase(.28,3.3,35,.8,7,3.0,65,10),
  Photography:activityBase(.12,1.1,45,.25,9,1.1,35,20),
  Laundry:clamp(100-rain*.72-Math.max(0,humidity-65)*.75-Math.max(0,uv-11)*1.5+(gust>=8&&gust<=28?6:0)-(codes.some(c=>[95,96,99].includes(c))?45:0)),
  'Outdoor event':activityBase(.38,3.1,30,1.1,6,3.3,70,16)
};
const nextTimes=sl(hourly.time,24),temps=sl(hourly.temperature_2m,24),rains=sl(hourly.precipitation_probability,24),winds=sl(hourly.wind_speed_10m,24),uvs=sl(hourly.uv_index,24);
let best={score:-999,start:null,end:null,why:''};
for(let x=0;x+2<nextTimes.length;x++){let s=100;const rr=Math.max(...rains.slice(x,x+3),0),ww=Math.max(...winds.slice(x,x+3),0),tt=Math.max(...temps.slice(x,x+3),0),uu=Math.max(...uvs.slice(x,x+3),0);s-=rr*.55;s-=Math.max(0,ww-20)*1.1;s-=Math.max(0,tt-32)*4;s-=Math.max(0,uu-6)*4;if(s>best.score)best={score:Math.round(s),start:nextTimes[x],end:nextTimes[x+2],why:`${Math.round(rr)}% peak rain, ${Math.round(ww)} km/h wind`}}
const completeness=[current.temperature_2m,current.relative_humidity_2m,current.apparent_temperature,current.wind_speed_10m,hourly.precipitation_probability?.length,hourly.uv_index?.length,hourly.visibility?.length,wx.daily?.time?.length,aq?.current?.european_aqi].filter(v=>v!==undefined&&v!==null).length;
return [{json:{...wx,place,airQuality:aq,insights:{risk:{score,level,reasons:reasons.length?reasons:['No major risk signal']},activities,bestOutdoorWindow:best,dataCompleteness:Math.round(completeness/9*100),recommendations:{umbrella:rain>=50,travel:score<61,outdoor:score<61},peakRain12h:Math.round(rain),peakUv12h:uv,minVisibility12h:minVis,generatedAt:new Date().toISOString(),engine:'WeatherGPT deterministic risk v1'}}}];
